const count = document.querySelector("#count")
let likes = 0
document.querySelector("#like").addEventListener("click", () => {
  likes++
  count.textContent = likes
})
const greeting = document.querySelector("#greeting")
document.querySelector("#name").addEventListener("input", (e) => {
  greeting.textContent = `Hello, ${e.target.value.trim() || "stranger"}!`
})
document.querySelector("#theme").addEventListener("click", () => document.body.classList.toggle("dark"))
document.querySelector("#search").addEventListener("keydown", (e) => {
  if (e.key === "Enter") document.querySelector("#searched").textContent = `Searching for: ${e.target.value}`
})
